package com.jagan.healthcare.dto;
import jakarta.validation.constraints.*; import java.time.*;
public class AppointmentRequest { @NotBlank @Size(max=100) private String patientName; @Email @Size(max=150) private String patientEmail; @NotBlank @Size(max=100) private String doctorName; @NotNull @FutureOrPresent private LocalDate appointmentDate; @NotNull private LocalTime appointmentTime; @Size(max=500) private String reason; public AppointmentRequest(){} public String getPatientName(){return patientName;} public String getPatientEmail(){return patientEmail;} public String getDoctorName(){return doctorName;} public LocalDate getAppointmentDate(){return appointmentDate;} public LocalTime getAppointmentTime(){return appointmentTime;} public String getReason(){return reason;} public void setPatientName(String v){patientName=v;} public void setPatientEmail(String v){patientEmail=v;} public void setDoctorName(String v){doctorName=v;} public void setAppointmentDate(LocalDate v){appointmentDate=v;} public void setAppointmentTime(LocalTime v){appointmentTime=v;} public void setReason(String v){reason=v;} }
